import{_ as a,o,c as t,a3 as r}from"./chunks/framework.CchDE9cb.js";const n="/capacitylens/assets/resource-form.Cglfjpl-.jpg",s="/capacitylens/assets/resources-external.DrCKs7nV.jpg",y=JSON.parse(`{"title":"People and placeholders","description":"Add real teammates and freelancers to the schedule, use a placeholder for a role you haven't filled, or book an outside company you don't manage.","frontmatter":{"title":"People and placeholders","description":"Add real teammates and freelancers to the schedule, use a placeholder for a role you haven't filled, or book an outside company you don't manage."},"headers":[],"relativePath":"guide/people-and-placeholders.md","filePath":"guide/people-and-placeholders.md","lastUpdated":null}`),i={name:"guide/people-and-placeholders.md"};function l(d,e,h,c,p,g){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="people-and-placeholders" tabindex="-1">People and placeholders <a class="header-anchor" href="#people-and-placeholders" aria-label="Permalink to &quot;People and placeholders&quot;">​</a></h1><p>Anyone who appears on <a href="/capacitylens/guide/the-schedule">the schedule</a> is a <a href="/capacitylens/reference/glossary">person</a> — added on the <strong>Resources</strong> page. This page covers adding real people and editing their details, using placeholders for roles you haven&#39;t filled, booking <a href="/capacitylens/reference/glossary">external parties</a> you hand work to but don&#39;t manage, and archiving someone who leaves.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>A person on the schedule doesn&#39;t get a CapacityLens sign-in, and inviting a <a href="/capacitylens/reference/glossary">member</a> doesn&#39;t put them on the schedule. These are deliberately separate — see <a href="/capacitylens/getting-started/roles-and-permissions">Roles and permissions</a>.</p></div><h2 id="add-a-person" tabindex="-1">Add a person <a class="header-anchor" href="#add-a-person" aria-label="Permalink to &quot;Add a person&quot;">​</a></h2><ol><li>Open <strong>Resources</strong>.</li><li>Click <strong>Add resource</strong>.</li><li>Fill in the fields below and save.</li></ol><p><img src="'+n+'" alt="The Add resource form with Name, Role, Discipline, Employment, Working hours / day and Working days fields"></p><ul><li><strong>Name</strong> — required.</li><li><strong>Role</strong> — a free-text label, for example &quot;Senior Designer&quot;. Optional.</li><li><strong>Discipline</strong> — which group this person shows under on the schedule, and where their colour comes from. Only shown if your company uses <a href="/capacitylens/reference/glossary">disciplines</a>, which is the default. Disciplines themselves are created and coloured on the standalone <strong>Disciplines</strong> page in the main navigation, not here — see <a href="/capacitylens/guide/settings">Settings</a> for the on/off switch.</li><li><strong>Employment</strong> — Permanent, Freelancer or Contractor. This is a label for your own filtering and reporting; it doesn&#39;t change how utilisation is worked out. Adding someone works exactly the same way whichever you pick.</li><li><strong>Working hours / day</strong> — how many hours a day this person is available for.</li><li><strong>Working days</strong> — which weekdays they work.</li></ul><p>Working hours and working days drive the utilisation figures directly: they&#39;re what CapacityLens compares a person&#39;s bookings against to decide whether they&#39;re over capacity. Get these two fields right, or the overwork indicators on <a href="/capacitylens/guide/the-schedule#reading-overwork">the schedule</a> will be wrong for that person.</p><p>The new row appears on the schedule immediately, ready for allocations and time off. There&#39;s no account to create and nothing for the person to sign in to.</p><h2 id="edit-a-person" tabindex="-1">Edit a person <a class="header-anchor" href="#edit-a-person" aria-label="Permalink to &quot;Edit a person&quot;">​</a></h2><ol><li>Open <strong>Resources</strong>.</li><li>Click the edit icon next to the person&#39;s row.</li><li>Change any field and save.</li></ol><p>For example, if someone goes part-time, open their row and turn off the weekdays they no longer work in <strong>Working days</strong>. The change applies going forward: past allocations and reports aren&#39;t rewritten, but every utilisation figure you see after saving reflects their new working days.</p><h2 id="placeholders" tabindex="-1">Placeholders <a class="header-anchor" href="#placeholders" aria-label="Permalink to &quot;Placeholders&quot;">​</a></h2><p>A <a href="/capacitylens/reference/glossary">placeholder</a> is a slot on the schedule for a role you know is coming but haven&#39;t hired or assigned yet — &quot;a Design Lead&quot; instead of a named person. Placeholders are off by default; an Owner or Admin turns them on for the company in <a href="/capacitylens/guide/settings">Settings</a>.</p><p>Once turned on, the Resources page shows a separate <strong>Placeholders</strong> section with its own <strong>Add placeholder</strong> button. A placeholder&#39;s name is optional — you can leave it blank and it shows by its role instead — but it must be bound to a project, since a placeholder only makes sense as capacity you&#39;re planning to book against specific work. Placeholder rows carry a small &quot;placeholder&quot; badge so they&#39;re never mistaken for a real person, and the same hatched styling carries through to their row on the schedule.</p><p>Turning placeholders off in Settings doesn&#39;t delete them — it hides the section, the schedule rows and the assignee picker entry, and everything reappears if you turn the setting back on.</p><h2 id="external-parties" tabindex="-1">External parties <a class="header-anchor" href="#external-parties" aria-label="Permalink to &quot;External parties&quot;">​</a></h2><p>An <a href="/capacitylens/reference/glossary">external party</a> is an outside company you hand work to but don&#39;t manage — a print shop, an overflow studio, a freelance agency you brief rather than schedule directly. They can appear on the schedule so you can see the handoff, but they carry no hours and never count toward your team&#39;s capacity or utilisation.</p><p>Use an external party instead of a placeholder when the work is genuinely leaving your team — there&#39;s no working-hours or working-days figure to set, because there&#39;s no capacity to track. Use a placeholder instead when you&#39;re planning to fill the work with someone on your own team&#39;s capacity, even if you haven&#39;t hired or named them yet.</p><p>External parties are off by default; an Owner or Admin turns them on for the company in <a href="/capacitylens/guide/settings">Settings</a>.</p><ol><li>Open <strong>Resources</strong>.</li><li>Under <strong>External</strong>, click <strong>Add external party</strong>.</li><li>Fill in <strong>Company</strong> (required) and, optionally, a <strong>Descriptor</strong> — for example &quot;Print&quot; or &quot;Overflow dev&quot; — and save.</li></ol><p><img src="'+s+'" alt="The Resources page with the External section, its Add external party button and an existing external row"></p><p>Turning external parties off in Settings hides the section and its rows the same way placeholders do, without deleting anything.</p><h2 id="archive-someone-who-leaves" tabindex="-1">Archive someone who leaves <a class="header-anchor" href="#archive-someone-who-leaves" aria-label="Permalink to &quot;Archive someone who leaves&quot;">​</a></h2><p>Deleting a person outright isn&#39;t the first step — removing a row from the Resources list archives it instead. Archiving hides the person from the schedule and the assignee picker but keeps their history, so past allocations and reports aren&#39;t rewritten.</p><ol><li>Open <strong>Resources</strong>.</li><li>Click the delete icon next to the person&#39;s row.</li><li>Confirm <strong>Archive resource?</strong></li></ol><p>To bring someone back, or to permanently delete an archived record after the appropriate waiting period, use <strong>Archived &amp; deleted</strong> in <a href="/capacitylens/guide/settings">Settings</a>.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><p><a href="/capacitylens/guide/projects-and-allocations">Projects and allocations</a> covers booking a person&#39;s time against real work, and <a href="/capacitylens/guide/time-off">Time off</a> covers marking them unavailable.</p>',29)])])}const f=a(i,[["render",l]]);export{y as __pageData,f as default};
